template<class M> void Unk_GuildTree(void* p,const void* q)
{
    new(p) M; ((M*)p)->~M();
    typedef std::_Tree_val<typename M::_Mybase::_Val_types> V;
    typename M::_Nodeptr n=*(typename M::_Nodeptr*)q;
    new(p) typename M::const_iterator(n,(const V*)q);
}
template<class M> void Unk_GuildTreeIter(void* p,const void* q)
{
    typedef std::_Tree_val<typename M::_Mybase::_Val_types> V;
    new(p) typename M::iterator(*(typename M::_Nodeptr*)q,(const V*)q);
}
template<class M> void Unk_GuildTreeDefIter(void* p)
{
    new(p) typename M::const_iterator;
}
template<class M> void Unk_GuildAtlNode(M& m,typename M::KINARGTYPE k,typename M::VINARGTYPE v)
{
    m.SetAt(k,v);
}
